(function(){"use strict";app.factory("docRecibidoService",function(t){const e="Compra/DocumentoRecibido/";let n=t.get("mainService"),u={get:function(t){return n.getData("get",e+"Get/"+JSON.stringify(t),null,!0).then(e=>{if("0"===e.code)throw e;if("1"===e.code){let n=JSON.parse(e.payload);return t.tipo&&"1"===t.tipo?n:(t.tipo&&t.tipo,n[0])}})},readFileTxt:function(t){return n.getDataFile(`${e}Read`,t,null,!0)},uploadXml:function(t,u){return n.getDataFile(`${e}UploadXml/?json=${JSON.stringify(t)}`,u,null,!0)},checkExistenceXml:function(t){return n.getData("post",`${e}CheckExistenceXml/?claveAcceso=${t}`,null,!0)},post:function(t){return n.getData("post",`${e}Post`,{data:t},!0).then(t=>t)},putXml:function(t){return n.getData("put",`${e}Put/${t}`,null,!0)},putXmlManual:function(t,u){return n.getDataFile(`${e}${t}/${u}`,file,null,!0)},delete:function(t){return n.getData("delete",`${e}${t}`,null,!0)},getId:function(t){return n.getData("get",`${e}GetId/${t}`,null,!0)}};return u})})(window.angular);